// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        bytes memory payload = abi.encodeWithSelector(c.setOwner.selector, newOwner);
        (bool success, bytes memory returnData) = address(c).call(payload);
        bool returnedTrue = false;
        if (success && returnData.length >= 32) {
            returnedTrue = abi.decode(returnData, (bool));
        }

        assertTrue(success && returnedTrue);
    }
}
